const names={food:'Продовольствие',grain:'Зерно',flour:'Мука',tools:'Инструменты',iron:'Железо','iron-ore':'Руда',timber:'Древесина',charcoal:'Уголь',fiber:'Волокно',yarn:'Пряжа',cloth:'Ткань',clothing:'Одежда'};
